var ENT=[["Charter", "Signature Charter pillar of the Progress Monitor framework."], ["Decomposer", "Signature Decomposer pillar of the Progress Monitor framework."], ["Planner", "Signature Planner pillar of the Progress Monitor framework."], ["Estimator", "Signature Estimator pillar of the Progress Monitor framework."], ["Sentinel", "Signature Sentinel pillar of the Progress Monitor framework."], ["Arbiter", "Signature Arbiter pillar of the Progress Monitor framework."], ["Ledger", "Signature Ledger pillar of the Progress Monitor framework."]];
